import json
import numpy as np
from scipy.interpolate import interp1d
from scipy.optimize import brentq

# Problem constants
N_cells = 16
I_cell = 60  # A
R_cell = 0.93e-3  # Ohm
q_cell = I_cell**2 * R_cell  # W per cell
Q_heat = N_cells * q_cell  # Total heat W
L_ch = 0.602  # m
L_pipe = 3.1  # m
d_pipe = 10e-3  # m
K_pipe = 9
T_in = 18  # C
R_cp = 0.2  # K/W

coolants_db = {
    'MEG-50': {
        'freeze': -36,
        'T': [10, 30, 50],
        'rho': [1070, 1059.4, 1047.1],
        'cp': [3258, 3364, 3459],
        'mu': [5.257, 2.729, 1.678],  # mPa·s
        'k': [0.383, 0.3953, 0.4077],
    }
}

pumps_db = {
    'PMP-1': {'P_rated': 7.6, 'price': 19.08, 'curve': [[0, 11148], [1.86, 8918], [2.97, 5017], [3.72, 0]]},
    'PMP-2': {'P_rated': 16.6, 'price': 28.34, 'curve': [[0, 18940], [3.79, 15152], [6.06, 8523], [7.58, 0]]},
    'PMP-3': {'P_rated': 38.1, 'price': 36.80, 'curve': [[0, 38850], [7.77, 31080], [12.43, 17482], [15.54, 0]]},
    'PMP-4': {'P_rated': 73.3, 'price': 63.24, 'curve': [[0, 50655], [10.13, 40524], [16.21, 22795], [20.26, 0]]},
    'PMP-5': {'P_rated': 134.7, 'price': 105.45, 'curve': [[0, 72880], [14.58, 58304], [23.32, 32796], [29.15, 0]]},
}

tube_prices = {4: 1.10, 6: 1.18, 8: 1.69, 10: 2.04, 12: 3.65}

def interp_prop(T, T_list, prop_list):
    if T <= T_list[0]: return prop_list[0]
    if T >= T_list[-1]: return prop_list[-1]
    return np.interp(T, T_list, prop_list)

def get_props(T, coolant_id):
    c = coolants_db[coolant_id]
    return {
        'rho': interp_prop(T, c['T'], c['rho']),
        'cp': interp_prop(T, c['T'], c['cp']),
        'mu': interp_prop(T, c['T'], c['mu']) * 1e-3,  # Pa·s
        'k': interp_prop(T, c['T'], c['k']),
    }

def friction_factor(Re):
    return 64/Re if Re < 2300 else 0.316 * Re**(-0.25)

def calc_system(Qv_Lmin, d_mm, n_par, coolant_id):
    Qv = Qv_Lmin / 60000  # m³/s
    d = d_mm * 1e-3

    # Solve T_out self-consistently
    T_out = T_in + 2
    for _ in range(20):
        T_m = (T_in + T_out) / 2
        props = get_props(T_m, coolant_id)
        T_out_new = T_in + Q_heat / (props['rho'] * Qv * props['cp'])
        if abs(T_out_new - T_out) < 0.001:
            break
        T_out = T_out_new

    T_m = (T_in + T_out) / 2
    props = get_props(T_m, coolant_id)

    # Channel
    v_ch = (Qv / n_par) / (np.pi * d**2 / 4)
    Re_ch = props['rho'] * v_ch * d / props['mu']
    f_ch = friction_factor(Re_ch)
    dP_ch = f_ch * (L_ch / d) * props['rho'] * v_ch**2 / 2

    # Pipe
    v_pipe = Qv / (np.pi * d_pipe**2 / 4)
    Re_pipe = props['rho'] * v_pipe * d_pipe / props['mu']
    f_pipe = friction_factor(Re_pipe)
    dP_pipe = (f_pipe * L_pipe / d_pipe + K_pipe) * props['rho'] * v_pipe**2 / 2

    dP_sys = dP_ch + dP_pipe

    # Thermal
    Pr = props['mu'] * props['cp'] / props['k']
    Nu = 4.36 if Re_ch < 2300 else 0.023 * Re_ch**0.8 * Pr**0.4
    h = Nu * props['k'] / d
    q_flux = (Q_heat / n_par) / (np.pi * d * L_ch)
    T_cell = T_out + q_flux / h + q_cell * R_cp

    return {
        'dP_sys': dP_sys, 'T_out': T_out, 'Re_ch': Re_ch, 'v_ch': v_ch, 'T_cell': T_cell
    }

def pump_dP(Qv_Lmin, pump_id, s):
    curve = np.array(pumps_db[pump_id]['curve'])
    f = interp1d(curve[:, 0], curve[:, 1], kind='linear', bounds_error=False, fill_value='extrapolate')
    return s**2 * f(Qv_Lmin / s)

def find_operating_point(pump_id, s, d_mm, n_par, coolant_id):
    curve = np.array(pumps_db[pump_id]['curve'])
    Qv_max = curve[-1, 0] * s * 0.99

    def residual(Qv):
        if Qv <= 0 or Qv > Qv_max:
            return 1e10
        return pump_dP(Qv, pump_id, s) - calc_system(Qv, d_mm, n_par, coolant_id)['dP_sys']

    try:
        return brentq(residual, 0.001, Qv_max)
    except:
        return None

# Main optimization
results = []
for coolant_id in ['MEG-50']:
    if coolants_db[coolant_id]['freeze'] > -20:
        continue

    for pump_id in pumps_db.keys():
        for s_val in np.arange(0.30, 1.01, 0.05):
            for d_mm in [4, 6, 8, 10, 12]:
                for n_par in [1, 2, 3, 4]:
                    Qv_op = find_operating_point(pump_id, s_val, d_mm, n_par, coolant_id)
                    if Qv_op is None:
                        continue

                    r = calc_system(Qv_op, d_mm, n_par, coolant_id)

                    # Constraint checks
                    if r['T_cell'] > 24 or r['T_out'] - T_in > 4 or r['v_ch'] > 1:
                        continue
                    if 2000 < r['Re_ch'] < 3000:
                        continue

                    P_pump = pumps_db[pump_id]['P_rated'] * s_val**3
                    if P_pump > 15:
                        continue

                    cost = pumps_db[pump_id]['price'] + n_par * L_ch * tube_prices[d_mm]
                    if cost > 39:
                        continue

                    results.append({
                        'coolant': coolant_id,
                        'pump': pump_id,
                        'speed': s_val,
                        'channel_d_mm': d_mm,
                        'n_parallel': n_par,
                        'P_pump': P_pump,
                    })

if results:
    results.sort(key=lambda x: x['P_pump'])
    min_P = results[0]['P_pump']
    best = [r for r in results if r['P_pump'] <= min_P * 1.05][0]
    print(json.dumps({
        'coolant': best['coolant'],
        'pump': best['pump'],
        'speed': round(best['speed'], 2),
        'channel_d_mm': best['channel_d_mm'],
        'n_parallel': best['n_parallel'],
    }))
